import{_ as n,o as s,c as t,a5 as e}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"82. 可移植性和字节顺序","description":"The Little Book of C 中文版 — 82. 可移植性和字节顺序","frontmatter":{"title":"82. 可移植性和字节顺序","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","09-可移植与现代 C","中文"],"description":"The Little Book of C 中文版 — 82. 可移植性和字节顺序","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":82,"sidebarWeight":82,"alternateZh":"/posts/c教程/zh-CN/09-可移植与现代 C/082-Portability and Endianness","alternateEn":"/posts/c教程/en-US/09-Portable and Modern C/082-Portability and Endianness"},"headers":[],"relativePath":"posts/c教程/zh-CN/09-可移植与现代 C/082-Portability and Endianness.md","filePath":"posts/c教程/zh-CN/09-可移植与现代 C/082-Portability and Endianness.md","lastUpdated":1790163617000}'),i={name:"posts/c教程/zh-CN/09-可移植与现代 C/082-Portability and Endianness.md"};function p(l,a,o,d,c,r){return s(),t("div",null,[...a[0]||(a[0]=[e(`<p>[English version](/posts/c教程/en-US/09-Portable and Modern C/082-Portability and Endianness)</p><p>可移植性意味着您的 C 程序在任何地方（Linux、Windows、ARM、x86，甚至微型微控制器）都以相同的方式运行。编写可移植代码是系统编程中最难也是最重要的技能之一。</p><p>本节帮助您了解最大的低级陷阱：字节顺序，以及如何编写跨架构安全运行的代码。</p><h4 id="步骤-1-什么是可移植性" tabindex="-1">步骤 1. 什么是可移植性？ <a class="header-anchor" href="#步骤-1-什么是可移植性" aria-label="Permalink to &quot;步骤 1. 什么是可移植性？&quot;">​</a></h4><p>可移植的 C 程序是这样的：</p><ul><li>使用不同的编译器进行干净的编译。</li><li>在 32 位、64 位和嵌入式系统上正确运行。</li><li>不假设 CPU、操作系统或编译器行为的详细信息。</li></ul><p>可移植性取决于尊重 C 标准的保证，并避免仅在您的机器上正确的假设。</p><h4 id="第-2-步-为什么可移植性很重要" tabindex="-1">第 2 步：为什么可移植性很重要 <a class="header-anchor" href="#第-2-步-为什么可移植性很重要" aria-label="Permalink to &quot;第 2 步：为什么可移植性很重要&quot;">​</a></h4><p>您可能会在 macOS (little-endian x86_64) 上编写一个 C 程序，稍后需要在以下设备上运行它：</p><ul><li>Raspberry Pi（ARM，也是小端）</li><li>大端 PowerPC 路由器</li><li>嵌入式 MIPS 控制器</li></ul><p>如果您的程序读取或写入二进制数据，则它必须处理字节顺序，否则同一文件可能会在另一个体系结构上被误读。</p><h4 id="步骤-3-了解字节顺序" tabindex="-1">步骤 3. 了解字节顺序 <a class="header-anchor" href="#步骤-3-了解字节顺序" aria-label="Permalink to &quot;步骤 3. 了解字节顺序&quot;">​</a></h4><p>字节顺序定义了多字节值的字节如何存储在内存中。</p><table tabindex="0"><thead><tr><th>类型</th><th>描述</th><th>内存（4 字节 int = 0x12345678）</th></tr></thead><tbody><tr><td>小尾数</td><td>最低有效字节在前</td><td><code>78 56 34 12</code></td></tr><tr><td>大尾数</td><td>最重要字节在前</td><td><code>12 34 56 78</code></td></tr></tbody></table><p>Intel 和 ARM（在大多数模式下）都是小端字节序。许多较旧的 CPU（PowerPC、SPARC）都是大端字节序。</p><p>C 没有定义字节顺序，它取决于平台。</p><h4 id="步骤-4-在运行时检查字节顺序" tabindex="-1">步骤 4. 在运行时检查字节顺序 <a class="header-anchor" href="#步骤-4-在运行时检查字节顺序" aria-label="Permalink to &quot;步骤 4. 在运行时检查字节顺序&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    unsigned int x = 0x12345678;</span></span>
<span class="line"><span>    unsigned char *p = (unsigned char *)&amp;x;</span></span>
<span class="line"><span>    if (*p == 0x78)</span></span>
<span class="line"><span>        printf(&quot;Little-endian\\n&quot;);</span></span>
<span class="line"><span>    else</span></span>
<span class="line"><span>        printf(&quot;Big-endian\\n&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>说明： 指针<code>p</code>读取最低内存字节。如果它包含最低有效字节（<code>0x78</code>)，它是小端字节序。</p><h4 id="步骤-5-在字节序之间转换" tabindex="-1">步骤 5. 在字节序之间转换 <a class="header-anchor" href="#步骤-5-在字节序之间转换" aria-label="Permalink to &quot;步骤 5. 在字节序之间转换&quot;">​</a></h4><p>使用标准 POSIX 函数安全地处理转换：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;arpa/inet.h&gt;</span><span>  // or &lt;winsock2.h&gt; on Windows</span></span>
<span class="line"><span>#include &lt;stdint.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    uint32_t x = 0x12345678;</span></span>
<span class="line"><span>    uint32_t y = htonl(x); // Host to Network Long (big-endian)</span></span>
<span class="line"><span>    printf(&quot;0x%x -&gt; 0x%x\\n&quot;, x, y);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>功能：</p><p>-<code>htons</code>– 主机到网络短（16 位） -<code>htonl</code>– 主机到网络长（32 位） -<code>ntohs</code>– 网络到主机短 -<code>ntohl</code>– 网络到主机长</p><p>网络字节顺序始终是大端字节序。</p><h4 id="步骤-6-处理文件格式的可移植性" tabindex="-1">步骤 6. 处理文件格式的可移植性 <a class="header-anchor" href="#步骤-6-处理文件格式的可移植性" aria-label="Permalink to &quot;步骤 6. 处理文件格式的可移植性&quot;">​</a></h4><p>如果将结构直接序列化到磁盘：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fwrite(&amp;header, sizeof(header), 1, file);</span></span></code></pre></div><p>你可能正在编写与机器相关的数据：</p><ul><li>字节顺序可能不同。</li><li>填充和对齐方式可能有所不同。</li><li>结构布局可能因编译器而异。</li></ul><p>更好的方法：按照明确的顺序单独编写每个字段：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uint32_t size_net = htonl(header.size);</span></span>
<span class="line"><span>fwrite(&amp;size_net, sizeof(size_net), 1, file);</span></span></code></pre></div><p>现在，任何机器都可以通过反转转换来读取您的文件（<code>ntohl</code>).</p><h4 id="步骤-7-数据类型大小差异" tabindex="-1">步骤 7. 数据类型大小差异 <a class="header-anchor" href="#步骤-7-数据类型大小差异" aria-label="Permalink to &quot;步骤 7. 数据类型大小差异&quot;">​</a></h4><p>不同系统的字体大小有所不同：</p><table tabindex="0"><thead><tr><th>类型</th><th>典型 32 位</th><th>典型 64 位</th></tr></thead><tbody><tr><td><code>char</code></td><td>1 字节</td><td>1 字节</td></tr><tr><td><code>short</code></td><td>2 个字节</td><td>2 个字节</td></tr><tr><td><code>int</code></td><td>4 字节</td><td>4 字节</td></tr><tr><td><code>long</code></td><td>4 字节</td><td>8 字节</td></tr><tr><td><code>long long</code></td><td>8 字节</td><td>8 字节</td></tr><tr><td><code>void*</code></td><td>4 字节</td><td>8 字节</td></tr></tbody></table><p>使用<code>&lt;stdint.h&gt;</code>类型（<code>int32_t</code>,<code>uint64_t</code>等）以获得可预测的尺寸。</p><h4 id="步骤-8-对齐和填充" tabindex="-1">步骤 8. 对齐和填充 <a class="header-anchor" href="#步骤-8-对齐和填充" aria-label="Permalink to &quot;步骤 8. 对齐和填充&quot;">​</a></h4><p>编译器可能会在结构字段之间插入填充以提高速度或对齐。</p><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>struct Example {</span></span>
<span class="line"><span>    char a;</span></span>
<span class="line"><span>    int b;</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>在大多数系统上：</p><p>-<code>sizeof(struct Example)</code>= 8，而不是 5（3 个字节的填充）。</p><p>要制作可移植格式：</p><ul><li>使用<code>#pragma pack(1)</code>（非标准）或逐个字段序列化。</li><li>永远不要假设<code>sizeof(struct)</code>跨系统都是一样的。</li></ul><h4 id="步骤-9-编译器和操作系统差异" tabindex="-1">步骤 9. 编译器和操作系统差异 <a class="header-anchor" href="#步骤-9-编译器和操作系统差异" aria-label="Permalink to &quot;步骤 9. 编译器和操作系统差异&quot;">​</a></h4><p>小心：</p><ul><li>路径分隔符（<code>/</code>与<code>\\\\</code>)</li><li>换行约定（<code>\\n</code>与<code>\\r\\n</code>) -<code>#include &lt;unistd.h&gt;</code>（仅限 POSIX） -<code>system()</code>命令（特定于操作系统）</li><li>线程 API (<code>pthread</code>与 Windows 线程相比）</li><li>套接字 API（<code></code>与<code>&lt;winsock2.h&gt;</code>)</li></ul><p>使用条件编译：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#ifdef _WIN32</span></span>
<span class="line"><span>#include &lt;winsock2.h&gt;</span></span>
<span class="line"><span>#else</span></span>
<span class="line"><span>#include &lt;arpa/inet.h&gt;</span></span>
<span class="line"><span>#endif</span></span></code></pre></div><h4 id="步骤-10-小代码-编写可移植二进制-i-o" tabindex="-1">步骤 10. 小代码：编写可移植二进制 I/O <a class="header-anchor" href="#步骤-10-小代码-编写可移植二进制-i-o" aria-label="Permalink to &quot;步骤 10. 小代码：编写可移植二进制 I/O&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;stdint.h&gt;</span></span>
<span class="line"><span>#include &lt;arpa/inet.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    FILE *f = fopen(&quot;num.bin&quot;, &quot;wb&quot;);</span></span>
<span class="line"><span>    uint32_t n = 0x12345678;</span></span>
<span class="line"><span>    uint32_t net = htonl(n);</span></span>
<span class="line"><span>    fwrite(&amp;net, sizeof(net), 1, f);</span></span>
<span class="line"><span>    fclose(f);</span></span>
<span class="line"><span>    f = fopen(&quot;num.bin&quot;, &quot;rb&quot;);</span></span>
<span class="line"><span>    uint32_t read_net;</span></span>
<span class="line"><span>    fread(&amp;read_net, sizeof(read_net), 1, f);</span></span>
<span class="line"><span>    fclose(f);</span></span>
<span class="line"><span>    printf(&quot;Read back: 0x%x\\n&quot;, ntohl(read_net));</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>该程序以可移植大端形式写入和读取 32 位整数，在任何机器上都是相同的字节。</p><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p>可移植性可确保您的软件比硬件的寿命更长。便携式程序：</p><ul><li>在不同的 CPU 和操作系统上运行。</li><li>跨架构安全地共享数据。</li><li>跨团队和系统建立对代码的信任。</li></ul><p>可移植性是一种专业精神，让您的代码面向未来。</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><ol><li>编写一个程序来检测并打印系统字节顺序。</li><li>将结构体序列化为二进制文件，然后在另一个系统上将其反序列化。</li><li>使用<code>htonl</code>和<code>ntohl</code>以确保数据保持一致。</li><li>使用 GCC 和 Clang 编译代码。</li><li>在 32 位和 64 位架构上进行测试。</li></ol><p>接下来，您将探索内联汇编和硬件访问，这是纯 C 和底层 CPU 指令之间的桥梁。</p>`,60)])])}const b=n(i,[["render",p]]);export{u as __pageData,b as default};
